import java.util.function.IntUnaryOperator;
import java.util.function.Supplier;

public class TallyMachineTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static void checkCall(String label, Object expected, java.util.concurrent.Callable<Object> call) {
        Object actual;
        try {
            actual = call.call();
        } catch (Throwable t) {
            actual = t.getClass().getSimpleName();
        }
        check(label, expected, actual);
    }

    public static void main(String[] args) {
        IntUnaryOperator tally = TallyMachine.runningTotal();
        checkCall("first add", 5, () -> tally.applyAsInt(5));
        checkCall("second add remembers the first", 8, () -> tally.applyAsInt(3));
        checkCall("negative amounts work too", 0, () -> tally.applyAsInt(-8));

        checkCall("a second tally starts fresh", 2, () -> TallyMachine.runningTotal().applyAsInt(2));
        checkCall("the first tally kept its own total", 4, () -> tally.applyAsInt(4));

        Supplier<String> tickets = TallyMachine.ticketDispenser(10);
        checkCall("first ticket", "T-10", () -> tickets.get());
        checkCall("tickets keep counting", "T-11T-12", () -> tickets.get() + tickets.get());
        checkCall("a second dispenser is independent", "T-1", () -> TallyMachine.ticketDispenser(1).get());

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

