import java.util.function.IntUnaryOperator;
import java.util.function.Supplier;

public class TallyMachine {

    public static IntUnaryOperator runningTotal() {
        int[] total = {0};
        return amount -> {
            total[0] += amount;
            return total[0];
        };
    }

    public static Supplier<String> ticketDispenser(int first) {
        int[] next = {first};
        return () -> {
            String ticket = "T-" + next[0];
            next[0]++;
            return ticket;
        };
    }
}
